// src/server/handlers.js — the pre-bundle original
const express = require("express");
const { exec } = require("child_process");
const db = require("./db");

const router = express.Router();

router.get("/api/v1/users/:id", async (req, res) => {
  const row = await db.query("SELECT * FROM users WHERE id = " + req.params.id);
  res.json(row);
});

router.get("/api/v1/export", (req, res) => {
  exec("tar czf /tmp/export.tgz " + req.query.dir, (err, stdout) => {
    res.send(stdout);
  });
});

router.get("/api/v1/avatar", (req, res) => {
  res.sendFile("/var/www/uploads/" + req.query.name);
});

router.post("/api/v1/fetch", (req, res) => {
  fetch(req.body.url).then((r) => r.text()).then((t) => res.send(t));
});

module.exports = router;
